<?php
if(!isset($manager,$user)){http_response_code(404);exit;}
$mode=($_GET['mode']??'month')==='week'?'week':'month';$date=(string)($_GET['date']??date('Y-m-d'));try{\Cosmos\Management::date($date);}catch(Throwable $e){$date=date('Y-m-d');}
$selected=new DateTimeImmutable($date);$first=$mode==='week'?$selected->modify('monday this week'):$selected->modify('first day of this month');$next=$mode==='week'?$first->modify('+7 days'):$first->modify('+1 month');$step=$mode==='week'?'week':'month';
$calendarBookings=$manager->query("SELECT id,reference,check_in,check_out,status,expires_at FROM bookings WHERE check_in<? AND check_out>? AND status IN ('inquiry','hold','confirmed')",[$next->format('Y-m-d'),$first->format('Y-m-d')]);$blocks=$manager->query('SELECT * FROM availability_blocks WHERE active=1 ORDER BY check_in');
?>
<div class="actions"><a class="button secondary" href="<?=ae(au('calendar',['date'=>$first->modify('-1 '.$step)->format('Y-m-d'),'mode'=>$mode]))?>">← Previous</a><strong><?=ae($mode==='week'?$first->format('j M').' – '.$next->modify('-1 day')->format('j M Y'):$first->format('F Y'))?></strong><a class="button secondary" href="<?=ae(au('calendar',['date'=>$first->modify('+1 '.$step)->format('Y-m-d'),'mode'=>$mode]))?>">Next →</a><a href="<?=ae(au('calendar',['mode'=>$mode==='month'?'week':'month','date'=>$date]))?>"><?=$mode==='month'?'Week view':'Month view'?></a><a href="<?=ae(au('calendar'))?>">Today</a></div>
<section class="card"><div class="calendar"><?php foreach(['Mon','Tue','Wed','Thu','Fri','Sat','Sun']as $weekday):?><span class="weekday"><?=$weekday?></span><?php endforeach;?><?php if($mode==='month')for($n=1;$n<(int)$first->format('N');$n++):?><span></span><?php endfor;?><?php for($day=$first;$day<$next;$day=$day->modify('+1 day')):$dayDate=$day->format('Y-m-d');$state='Available';$class='';$daily=[];foreach($blocks as $block)if($block['check_in']<=$dayDate&&$block['check_out']>$dayDate){$state='Blocked';$class='blocked';}foreach($calendarBookings as $booking)if($booking['check_in']<=$dayDate&&$booking['check_out']>$dayDate){if($booking['status']==='confirmed'){$state='Booked';$class='booked';}elseif($booking['status']==='hold'&&$booking['expires_at']>gmdate('Y-m-d H:i:s')){$state='Reserved';$class='reserved';}elseif($booking['status']==='hold')continue;$daily[]=$booking;}?><div class="day <?=$class?>"><strong><?=ae($day->format('j'))?></strong><small><?=ae($state)?></small><?php foreach($daily as $booking):?><a href="<?=ae(au('bookings',['id'=>$booking['id']]))?>"><?=ae($booking['reference'])?><?=$booking['status']==='inquiry'?' · enquiry':''?></a><?php endforeach;?><a href="<?=ae(au('bookings',['new'=>1,'date'=>$dayDate]))?>">+ Booking</a></div><?php endfor;?></div><p class="help">Available · Booked · Reserved · Blocked. Enquiries do not block dates. A guest can check in on the day another guest checks out.</p></section>
<section class="card"><h2>Block dates</h2><p class="help">Use this for maintenance or owner stays. The end date is the first available date.</p><?php form_start('block','calendar');input('check_in','From',$date,'date',true);input('check_out','Until','','date',true);input('reason','Reason','','text',true,'maxlength="200"');?><button>Block dates</button></form><?php if($blocks):?><div class="scroll"><table><thead><tr><th>From</th><th>Until</th><th>Reason</th><th>Action</th></tr></thead><tbody><?php foreach($blocks as $block):?><tr><td><?=ae($block['check_in'])?></td><td><?=ae($block['check_out'])?></td><td><?=ae($block['reason'])?></td><td><?php form_start('unblock','calendar',['id'=>$block['id']]);?><button class="secondary" data-confirm="Make these blocked dates available again?">Unblock</button></form></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
